// HasAnggota applies the HasEdge predicate on the "anggota" edge.
func HasAnggota() predicate.Keluarga {
	return predicate.Keluarga(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, AnggotaTable, AnggotaColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAnggotaWith applies the HasEdge predicate on the "anggota" edge with a given conditions (other predicates).
func HasAnggotaWith(preds ...predicate.Umat) predicate.Keluarga {
	return predicate.Keluarga(func(s *sql.Selector) {
		step := newAnggotaStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

